33257	Pesaquisa e Resultado de Pesquisa	draft	wpcode	// === CONFIGURE AQUI ===\nconst DSF_RESULTS_PAGE = '/pesquisa/';   // p gina de resultados (slug com barra inicial e final opcional)\nconst DSF_LOGIN_PAGE   = '/cadastro/';   // p gina de login/cadastro\n// ======================\n\n/**\n * Shortcode: [dsf_search_box placeholder="Digite..." button="Pesquisar" action="/pesquisa/"]\n */\nadd_shortcode('dsf_search_box', function ($atts = []) {\n    $a = shortcode_atts([\n        'placeholder' => 'Digite para pesquisar?',\n        'button'      => 'Pesquisar',\n        'action'      => DSF_RESULTS_PAGE,\n        'param'       => 's',\n        'value'       => get_search_query(),\n    ], $atts);\n\n    $action = esc_url(home_url($a['action']));\n    $param  = esc_attr($a['param']);\n    $value  = esc_attr($a['value']);\n    $ph     = esc_attr($a['placeholder']);\n    $btn    = esc_html($a['button']);\n\n    ob_start(); ?>\n    <form class="dsf-search-box" role="search" method="get" action="<?php echo $action; ?>">\n        <input type="search" name="<?php echo $param; ?>" value="<?php echo $value; ?>" placeholder="<?php echo $ph; ?>" />\n        <button type="submit"><?php echo $btn; ?></button>\n    </form>\n    <?php\n    return ob_get_clean();\n});\n\n/**\n * Shortcode: [dsf_search_results per_page="12" post_type="post"]\n * - Logado: t¡tulo com link + trecho (excerpt) + metadados (opcional)\n * - NÆo logado: apenas t¡tulo SEM link (ou link para login com redirect)\n * - Pagina‡Æo\n * - "Itens pr¢ximos" (busca aproximada por t¡tulo) quando nÆo houver resultados\n */\nadd_shortcode('dsf_search_results', function ($atts = []) {\n    global $wpdb;\n\n    $a = shortcode_atts([\n        'per_page'  => 12,\n        'post_type' => 'post',     // pode aceitar "any" ou CPTs separados por v¡rgula\n        'show_meta' => 'no',       // yes/no: mostra cas/ncm no excerpt (se fizer sentido pro seu template)\n        'link_when_logged_out' => 'login', // "none" (sem link) | "login" (linka pra /cadastro?redirect_to)\n    ], $atts);\n\n    $term  = isset($_GET['s']) ? wp_unslash($_GET['s']) : '';              // termo vindo da URL\n    $paged = max(1, (int) get_query_var('paged'));                          // suporta /page/2\n    if (!$term) return '<p>Digite um termo para pesquisar.</p>';\n\n    // Monta tipos de post\n    $post_types = array_map('trim', explode(',', $a['post_type']));\n    $post_types = array_filter($post_types);\n    if (empty($post_types)) { $post_types = ['post']; }\n\n    // Query principal (respeita relevƒncia nativa do WP)\n    $q = new WP_Query([\n        'post_type'           => $post_types,\n        's'                   => $term,\n        'posts_per_page'      => (int) $a['per_page'],\n        'paged'               => $paged,\n        'ignore_sticky_posts' => true,\n        'post_status'         => 'publish',\n    ]);\n\n    // Monta sa¡da\n    ob_start();\n\n    // T¡tulo com o termo pesquisado\n    echo '<div class="dsf-results-header">';\n    echo '<h2>Resultados para: <mark>' . esc_html($term) . '</mark></h2>';\n    echo '</div>';\n\n    // LISTA DE RESULTADOS\n    if ($q->have_posts()) {\n        echo '<ul class="dsf-results-list">';\n        while ($q->have_posts()) { $q->the_post();\n\n            $title = get_the_title();\n            $perma = get_permalink();\n            $excerpt = wp_trim_words( wp_strip_all_tags(get_the_content(null,false)), 30, '?' );\n\n            echo '<li class="dsf-result-item">';\n\n            if (is_user_logged_in()) {\n                // LOGADO: t¡tulo com link + excerpt\n                echo '<h3 class="dsf-result-title"><a href="' . esc_url($perma) . '">' . esc_html($title) . '</a></h3>';\n                echo '<div class="dsf-result-excerpt">' . esc_html($excerpt) . '</div>';\n            } else {\n                // NÇO LOGADO: t¡tulo sem link OU link para login com redirect\n                if ($a['link_when_logged_out'] === 'login') {\n                    $login_url = add_query_arg('redirect_to', rawurlencode($perma), home_url(DSF_LOGIN_PAGE));\n                    echo '<h3 class="dsf-result-title"><a href="' . esc_url($login_url) . '" class="dsf-locked" aria-label="Fa‡a login para ver detalhes">'\n                        . esc_html($title) . '</a></h3>';\n                    echo '<small class="dsf-locked-note">Fa‡a login para ver os detalhes.</small>';\n                } else {\n                    echo '<h3 class="dsf-result-title">' . esc_html($title) . '</h3>';\n                }\n            }\n\n            echo '</li>';\n        }\n        echo '</ul>';\n\n        // PAGINA€ÇO\n        $big = 999999999;\n        $links = paginate_links([\n            'base'      => str_replace($big, '%#%', esc_url(get_pagenum_link($big))),\n            'format'    => '?paged=%#%',\n            'current'   => $paged,\n            'total'     => (int) $q->max_num_pages,\n            'type'      => 'list',\n            'prev_text' => '® Anterior',\n            'next_text' => 'Pr¢ximo ¯',\n        ]);\n        if ($links) {\n            echo '<nav class="dsf-pagination">' . $links . '</nav>';\n        }\n\n    } else {\n        echo '<p><strong>Nenhum resultado exato</strong> para <em>' . esc_html($term) . '</em>.</p>';\n\n        // "ITENS PRàXIMOS" ? alternativa simples por t¡tulo (LIKE)\n        $like = '%' . $wpdb->esc_like($term) . '%';\n        $pt_placeholders = implode(',', array_fill(0, count($post_types), '%s'));\n        $sql = $wpdb->prepare(\n            "SELECT ID, post_title FROM {$wpdb->posts}\n             WHERE post_status='publish'\n               AND post_type IN ($pt_placeholders)\n               AND post_title LIKE %s\n             ORDER BY post_title ASC\n             LIMIT 10",\n            array_merge($post_types, [$like])\n        );\n        $candidates = $wpdb->get_results($sql);\n\n        if (!empty($candidates)) {\n            echo '<div class="dsf-suggestions">';\n            echo '<p>Tente tamb‚m:</p>';\n            echo '<ul>';\n            foreach ($candidates as $c) {\n                $t = esc_html($c->post_title);\n                $u = get_permalink($c->ID);\n\n                if (is_user_logged_in()) {\n                    echo '<li><a href="' . esc_url($u) . '">' . $t . '</a></li>';\n                } else {\n                    if ($a['link_when_logged_out'] === 'login') {\n                        $login_url = add_query_arg('redirect_to', rawurlencode($u), home_url(DSF_LOGIN_PAGE));\n                        echo '<li><a class="dsf-locked" href="' . esc_url($login_url) . '">' . $t . '</a></li>';\n                    } else {\n                        echo '<li>' . $t . '</li>';\n                    }\n                }\n            }\n            echo '</ul></div>';\n        }\n    }\n\n    wp_reset_postdata();\n    return ob_get_clean();\n});
